            int mid = (l + r) >> 1;
            if (a[mid] <= key) {
                l = mid + 1;
            } else {
                r = mid - 1;
            }
        }
        printf("%d ", l - 1 >= 1 && a[l - 1] == key ? l - 1 : -1);
    }
